284|export const buildRegionSubmitPayload = (
285|  formData: FormData,
286|  fieldMappings: RegionFormFieldMapping[],
287|  fieldTransforms?: Record<string, PayloadFieldTransform>,
288|): Record<string, unknown> => {
289|  const payload: Record<string, unknown> = {};
290|  const serverManagedColumns = new Set(['id', 'created_at', 'created_by', 'updated_at', 'updated_by']);
291|
292|  for (const mapping of fieldMappings) {
293|    if (serverManagedColumns.has(mapping.column)) {
294|      continue;
295|    }
296|
297|    const transform = mapping.payloadTransform ?? fieldTransforms?.[mapping.column];
298|    payload[mapping.column] = applyPayloadFieldTransform(
299|      formData.get(mapping.formFieldName),
300|      transform,
301|    );
302|  }
303|  return payload;
304|};
