322|export const resolveRegionSubmitFormData = (
323|  submitRoot: HTMLFormElement | ParentNode,
324|  fieldMappings: RegionFormFieldMapping[],
325|): FormData => {
326|  if (submitRoot instanceof HTMLFormElement) {
327|    return new FormData(submitRoot);
328|  }
329|
330|  return collectRegionFormDataFromContainer(
331|    submitRoot,
332|    fieldMappings.map((mapping) => mapping.formFieldName),
333|  );
334|};
