336|export const executeDesignerRegionSubmit = async (
337|  submitRoot: HTMLFormElement | ParentNode,
338|  binding: ResolvedEventBinding,
339|  bindingContext: Record<string, unknown>,
340|  callbacks: BindingMutationCallbacks = {},
341|  document?: DesignerDocument,
342|  designerStore: Record<string, unknown> = {},
343|): Promise<void> => {
344|  const plan = binding.regionSubmitPlan;
345|  if (!plan) {
346|    return;
347|  }
348|
349|  if (document) {
350|    const fieldErrors = validateRegionSubmitFields(submitRoot, plan.fieldMappings, document, designerStore);
351|    if (Object.keys(fieldErrors).length > 0) {
352|      callbacks.onFieldValidationErrors?.(fieldErrors);
353|      return;
354|    }
355|    callbacks.onFieldValidationErrors?.({});
356|  } else if (submitRoot instanceof HTMLFormElement && typeof submitRoot.reportValidity === 'function' && !submitRoot.reportValidity()) {
357|    return;
358|  }
359|
360|  const formData = resolveRegionSubmitFormData(submitRoot, plan.fieldMappings);
361|  const payload = buildRegionSubmitPayload(
362|    formData,
363|    plan.fieldMappings,
364|    binding.definition.payloadFieldTransforms,
365|  );
366|  const regionData = bindingContext[plan.dataVar] as Record<string, unknown> | undefined;
367|  const method = resolveRegionDmlMethod(regionData, plan.primaryKey);
368|  const endpointTemplate = method === 'POST'
369|    ? (plan.createEndpoint ?? plan.endpoint)
370|    : (plan.updateEndpoint ?? plan.endpoint);
371|  const endpoint = resolveRegionDmlUrl(endpointTemplate, regionData, plan.primaryKey);
372|
373|  await executeDesignerMutation(
374|    {
375|      ...binding,
376|      endpoint,
377|      actionType: method,
378|      urlParams: {},
379|      headers: {},
380|    },
381|    bindingContext,
382|    payload,
383|    callbacks,
384|  );
385|};
