387|export const executeDesignerFormSubmit = async (
388|  event: { preventDefault: () => void; currentTarget: HTMLFormElement },
389|  binding: ResolvedEventBinding,
390|  bindingContext: Record<string, unknown>,
391|  callbacks: BindingMutationCallbacks = {},
392|  document?: DesignerDocument,
393|  designerStore: Record<string, unknown> = {},
394|): Promise<void> => {
395|  event.preventDefault();
396|
397|  if (binding.regionSubmitPlan && document) {
398|    const fieldErrors = validateRegionSubmitFields(event.currentTarget, binding.regionSubmitPlan.fieldMappings, document, designerStore);
399|    if (Object.keys(fieldErrors).length > 0) {
400|      callbacks.onFieldValidationErrors?.(fieldErrors);
401|      return;
402|    }
403|    callbacks.onFieldValidationErrors?.({});
404|  } else if (typeof event.currentTarget.reportValidity === 'function' && !event.currentTarget.reportValidity()) {
405|    return;
406|  }
407|
408|  if (binding.storeWritePath) {
409|    callbacks.patchStore?.(binding.storeWritePath, true);
410|  }
411|
412|  if (binding.regionSubmitPlan) {
413|    await executeDesignerRegionSubmit(event.currentTarget, binding, bindingContext, callbacks, document, designerStore);
414|    return;
415|  }
416|
417|  if (!binding.endpoint) {
418|    return;
419|  }
420|
421|  const formData = new FormData(event.currentTarget);
422|  const payload = buildPayloadFromFormData(
423|    formData,
424|    binding.payloadMapping,
425|    binding.payloadFieldTransforms,
426|  );
427|
428|  await executeDesignerMutation(binding, bindingContext, payload, callbacks);
429|};
