432|  event: { target: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement },
433|  binding: ResolvedEventBinding,
434|  bindingContext: Record<string, unknown>,
435|  callbacks: BindingMutationCallbacks = {},
436|): Promise<void> => {
437|  if (binding.storeWritePath) {
438|    callbacks.patchStore?.(binding.storeWritePath, event.target.value);
